input.code:
async (page) => {
  const errs = [];
  page.on('pageerror', e => errs.push(String(e)));
  await page.goto('http://127.0.0.1:5197/jogo.html?id=guerra-tortas&sons=0');
  await page.waitForTimeout(3000);
  const P = (x, y) => [x * 1.28, 32 + y * 1.28];
  const dir = 'C:/Users/migue/Documents/hackathon-dopamine/.playwright-mcp/';
  await page.screenshot({ path: dir + 'gt-v2-1-inicio.png' });
  await page.mouse.click(...P(400, 395));
  await page.waitForTimeout(1500);
  await page.screenshot({ path: dir + 'gt-v2-2-jogo.png' });
  await page.keyboard.down('Space');
  await page.waitForTimeout(900);
  await page.screenshot({ path: dir + 'gt-v2-3-defendendo.png' });
  await page.waitForTimeout(1800);
  await page.keyboard.up('Space');
  await page.waitForTimeout(600);
  await page.screenshot({ path: dir + 'gt-v2-4-torta.png' });
  // espera o guaxinim baixar a guarda, tentando lançar algumas vezes
  for (let i = 0; i < 6; i++) { await page.mouse.click(...P(400, 200)); await page.waitForTimeout(700); }
  await page.waitForTimeout(800);
  await page.screenshot({ path: dir + 'gt-v2-5-depois.png' });
  return errs;
}

